      `<div class="card soft" style="margin-top:10px"><b>客户自己的收藏 / 打分</b><div class="small muted">客户在客户 App 里收藏、打分、写的一句话，这里和网站读同一份；客户的原话和 AI 的总结分开存。</div>${fbs.length ? fbs.map(([h, line]) => `<div class="small" style="margin-top:6px"><b>${esc(h.addr.split(",")[0])}</b>${line}</div>`).join("") : `<div class="tiny muted" style="margin-top:6px">这条路线上客户还没有收藏或打分</div>`}</div>`;
