  // 看房日（决定 42）：我到了 → 开锁信息显示 20 秒；完成 → 自动跳下一站并弹速记。没有有效的代理协议不让签到（决定 D29，和网站的看房模式同一个检查）
  A["show-arrive-now"] = (el, arg) => { const [tid, hid] = arg.split("|"); const t = NBTours.byId(tid); const h = t && t.homes.find((x) => x.id === hid); if (!h) return; const chk = NBTours.canStart(tid); if (!chk.ok) { toast(chk.why); return; } if (!(h.visit && h.visit.arrived)) NBTours.arrive(tid, hid); h.visit.arrivedTs = Date.now(); if (h.visit.left) delete h.visit.left; audit(t.deal, `看房：到场 ${h.addr.split(",")[0]} · 开锁信息显示 ${LOCK_S} 秒`, "system", "看房日"); DBsave(); render(); toast(`已签到 · 开锁信息 ${LOCK_S} 秒后隐藏`); };
  A["lock-show"] = (el, arg) => { const [tid, hid] = arg.split("|"); const t = NBTours.byId(tid); const h = t && t.homes.find((x) => x.id === hid); if (!h || !NBTours.here(h)) return; h.visit.arrivedTs = Date.now(); audit(t.deal, `看房：再显示一次开锁信息 ${h.addr.split(",")[0]}（${LOCK_S} 秒）`, "system", "看房日"); DBsave(); render(); };
  A["show-leave-next"] = (el, arg) => { const [tid, hid] = arg.split("|"); const t = NBTours.byId(tid); if (!t || !t.homes.some((x) => x.id === hid)) return; NBTours.leave(tid, hid); const allDone = t.homes.every(NBTours.visited); if (allDone) { M().tours = M().tours || {}; M().tours[tid] = { step: 3 }; } DBsave(); render(); toast(allDone ? "全部看完 → 速记跟进" : "已到下一站 · 顺手说 30 秒"); if (!allDone) setTimeout(() => A["show-voice"](null, `${tid}|${hid}`), 150); };
  A["tour-step"] = (el, arg) => { const [tid, n] = arg.split("|"); M().tours = M().tours || {}; M().tours[tid] = { step: Number(n) }; DBsave(); render(); };
  A["tour-start"] = (el, tid) => { if (!el || !el.value || !NBTours.byId(tid)) return; NBTours.setStart(tid, el.value); DBsave(); render(); toast(`出发时间改为 ${el.value} · 预计到达已重算，要重新同步`); };
  // 约看房（决定 D19）：系统只备好每一套的预约请求；发送是你自己点的，点了记一笔，不进任何自动队列
  A["tour-book"] = (el, tid) => { if (!NBTours.byId(tid)) return; const a = document.getElementById("tr-addrs"); const addrs = (a ? a.value : "").split("\n").map((x) => x.trim()).filter(Boolean); const r = NBTours.prepareRequests(tid, addrs); DBsave(); render(); toast(r.ready ? `备好了 ${r.ready} 套的预约请求${r.added ? "（新加 " + r.added + " 套）" : ""} · 逐套点发送` : "没有要约的：都已经发出或确认了"); };
  A["tour-req"] = (el, arg) => { const [tid, hid] = arg.split("|"); const dr = NBTours.requestDraft(tid, hid); if (!dr) return; openSheet(`<h2>预约请求 · 你点发送</h2><p class="small muted">系统只备稿：发送是你在预约网站上自己点的（${esc(dr.via)}）。</p><textarea id="tq-txt" rows="4" readonly>${esc(dr.text)}</textarea><div class="row" style="margin-top:10px"><button class="btn" data-action="nb-copy" data-arg="tq-txt">复制</button><span class="sp"></span><button class="btn pri" data-action="tour-send" data-arg="${arg}">我点了发送 · 记一笔</button></div>`); };
  A["tour-send"] = (el, arg) => { const [tid, hid] = arg.split("|"); const h = NBTours.sendRequest(tid, hid); closeSheet(); DBsave(); render(); toast(h ? "记下了：这一套的请求已发 · 等确认邮件" : "这一站不在预约中"); };
  A["tour-confirm"] = (el, arg) => { const [tid, hid] = arg.split("|"); const h = NBTours.confirmHome(tid, hid, {}); if (!h) return; DBsave(); render(); toast("确认邮件解析成功 · 这一站已确认并写入日历"); };
  A["tour-alt"] = (el, arg) => { const [tid, hid] = arg.split("|"); const tr = NBTours.byId(tid); const h = tr && tr.homes.find((x) => x.id === hid); if (!h) return; openSheet(`<h2>约不上 · 选一个替补时段</h2><p class="small muted">影响：${esc(h.impact || "预计到达会按新时段重算")}。只有你点了才改期，改完要重新同步。</p>${(h.alts || []).map((a) => `<button class="btn wide" style="margin-top:6px" data-action="tour-alt-ok" data-arg="${tid}|${hid}|${esc(a)}">${esc(a)}</button>`).join("") || `<div class="empty small">对方还没给替补时段</div>`}`); };
