  A["tour-sync"] = (el, tid) => { const pv = NBTours.syncPreview(tid); if (!pv) return; const sec = (t, rows) => `<div class="tiny muted" style="margin-top:8px">${t}</div>${rows.map((x) => `<div class="small">· ${esc(x)}</div>`).join("") || `<div class="small muted">· 没有要写的</div>`}`; openSheet(`<h2>同步预览</h2><p class="small muted">先看每个去处会写什么；客户 App 只收顺序、时间和集合点。</p>${sec("交易", pv.deal)}${sec("我的日历", pv.calendar)}${sec("经纪人 App", pv.agentApp)}${sec("客户 App", pv.clientApp)}<button class="btn wide pri" style="margin-top:12px" data-action="tour-sync-ok" data-arg="${tid}">写入并同步</button>`); };
  A["tour-sync-ok"] = (el, tid) => { if (!NBTours.sync(tid)) return; closeSheet(); DBsave(); render(); toast("已同步：交易 · 日历 · 两个 App（客户版只含路线）"); };
  A["tour-new"] = () => { const cs = DB.contacts.filter((c) => ["client", "lead"].includes(c.kind)); openSheet(`<h2>新建 tour</h2><p class="small muted">一个客户一次出行；同一天可以再给别的客户建一个。</p><label class="tiny muted">客户</label><select id="tn-c" style="width:100%">${cs.map((c) => `<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select><div class="row" style="margin-top:8px"><label class="small">日期 <input id="tn-date" type="date" value="${window.__d(1)}"></label><label class="small">出发 <input id="tn-start" type="time" value="10:00"></label></div><label class="tiny muted" style="display:block;margin-top:8px">房源地址（每行一套，可先空着）</label><textarea id="tn-addrs" rows="3"></textarea><button class="btn wide pri" style="margin-top:10px" data-action="tour-new-ok">建好 → 去约看房</button>`); };
