    const timeline = `<div class="card ptlcard"><div class="hd"><h3>历史时间线</h3><span class="tiny muted">新的在上</span></div>${tl.length ? `<div class="ptl">${tl.map((x) => `<div class="ptl-i" data-ptl="${esc(x.kind)}"><span class="ptl-dot ${esc(x.tone || "mute")}"></span><div class="ptl-at num">${esc(x.at)}</div><div class="ptl-body"><span class="badge ${esc(x.tone || "mute")}">${esc(x.label)}</span>${x.price != null ? `<b class="num small">${money(x.price)}</b>` : ""}${x.href ? `<a class="tiny" href="${x.href}">打开 →</a>` : ""}<div class="d">${esc(x.sub || "")}</div></div></div>`).join("")}</div>` : `<div class="empty small">还没有记录：「拍照 / 上传」传一份 Matrix History 报表或税务记录</div>`}<p class="tiny muted" style="margin:8px 0 0">挂牌 → 调价 → 进合同 → 成交 → 转手 + 产权人起止 + 这套房上的交易。</p></div>`;
    const dealsCard = `<div class="card"><div class="hd"><h3>这套房上的交易</h3><span class="tiny muted">一房多笔</span></div>${ds.length ? `<div class="list">${ds.map((d) => `<a class="li" href="#/deals/${d.id}"><div class="body"><div class="t small">${esc(d.title)} ${stageBadge(d.stage)}</div><div class="d">${NBRoadmap.sideLabel(d)} · ${esc((contact(d.primary) || {}).name || "")} · ${esc(NBRoadmap.nowText(d))}${d.type === "seller" && d.stage === "pre_listing" && !(d.rm || {}).pre ? " · 上市委托协议没完成 = 还在争取" : ""}${d.stage === "lost" ? " · 房源 / 业主 / 联系记录都留着" : ""}</div></div><span class="tiny muted">›</span></a>`).join("")}</div>` : `<div class="empty small">没有交易</div>`}${os ? "" : `<button class="btn xs" style="margin-top:8px" data-action="prop-seller-deal" data-arg="${id}">建卖方交易（落在上市前）</button>`}</div>`;
    const files = `<div class="card pdocs"><div class="hd"><h3>文件</h3><span class="tiny muted">只挂这套房 · 不挂交易</span></div>${pdocs.length ? `<div class="list">${pdocs.map((x) => { const st = DOCST[x.status] || [x.status, "mute"]; return `<div class="li pdoc ${x.status === "removed" ? "done" : ""}" data-pdoc="${x.id}" data-type="${esc(x.type)}"><span class="badge ${st[1]}">${st[0]}</span><div class="body"><div class="t small">${esc(x.name)}</div><div class="d">${esc(docTypeLabel(x))} · ${x.pages || 1} 页 · 上传 ${esc(x.uploaded)} · ${esc(x.source || "")}</div></div>${x.status !== "removed" ? `<button class="btn xs ghost" data-action="pf-doc-remove" data-arg="${x.id}">删除</button>` : ""}</div>`; }).join("")}</div>` : `<div class="empty small">还没有文件</div>`}<div class="row" style="margin-top:8px"><button class="btn sm pri" data-action="prop-upload" data-arg="${id}">拍照 / 上传</button></div><p class="tiny muted" style="margin:8px 0 0"><b>来源</b>：Matrix 文件是你自己导出的；私人备注 / 看房说明 / 门锁 / 业主联系方式发给模型前就删掉。手机拍的照片只存成这套房的文件，不抽取。</p></div>`;
    const notes = `<div class="card"><div class="hd"><h3>备注</h3><span class="tiny muted">只读 · 编辑在网站</span></div><p class="small" style="margin:0">${p.notes ? esc(p.notes) : "<span class='muted'>还没有备注</span>"}</p><div style="margin-top:8px">${relay("properties/" + id, "在网站编辑", "lk")}</div></div>`;
